cat > src/index.js <<'EOF'
import fsevents from 'fsevents';

/**
 * Watch a directory tree using macOS FSEvents.
 *
 * @param {string} root - Absolute or relative path to watch (recursive).
 * @param {(event: WatchEvent) => void} onEvent - Called for each change.
 * @returns {() => Promise<void>} Stop function; resolves once the stream is closed.
 *
 * @typedef {object} WatchEvent
 * @property {string} path - Absolute path of the changed entry.
 * @property {string} event - created | modified | deleted | moved | root-changed | unknown
 * @property {string} type - file | directory | symlink
 * @property {{inode: boolean, finder: boolean, access: boolean, xattrs: boolean}} changes
 * @property {number} flags - Raw FSEventStreamEventFlags bitmask.
 * @property {number} id - FSEvents event ID (monotonic, usable for resume-from-ID).
 */
export function watch(root, onEvent) {
  return fsevents.watch(root, (path, flags, id) => {
    const info = fsevents.getInfo(path, flags);
    onEvent({ ...info, id });
  });
}

export const constants = fsevents.constants;
EOF
cat > bin/mac-fswatch.js <<'EOF'
#!/usr/bin/env node
import { resolve } from 'node:path';
import { watch } from '../src/index.js';

const root = resolve(process.argv[2] ?? '.');
const json = process.argv.includes('--json');

const stop = watch(root, (e) => {
  if (json) {
    console.log(JSON.stringify(e));
  } else {
    console.log(`${e.event.padEnd(12)} ${e.type.padEnd(9)} ${e.path}`);
  }
});

console.error(`Watching ${root} (Ctrl+C to stop)`);

const shutdown = async () => {
  await stop();
  process.exit(0);
};
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
EOF
chmod +x bin/mac-fswatch.js
cat > test/watch.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, realpath, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

test('reports file creation', { skip: process.platform !== 'darwin' && 'FSEvents is macOS-only' }, async () => {
  const { watch } = await import('../src/index.js');
  // FSEvents reports canonical paths (/private/var/... rather than /var/...).
  const dir = await realpath(await mkdtemp(join(tmpdir(), 'mac-fswatch-')));
  const target = join(dir, 'hello.txt');

  const seen = new Promise((resolve) => {
    const stop = watch(dir, async (e) => {
      if (e.path === target && e.event === 'created') {
        await stop();
        resolve(e);
      }
    });
  });

  // Give the stream a moment to start before generating events.
  await new Promise((r) => setTimeout(r, 200));
  await writeFile(target, 'hi');

  const event = await seen;
  assert.equal(event.type, 'file');
  assert.equal(typeof event.id, 'number');
  await rm(dir, { recursive: true, force: true });
});
EOF
cat > README.md <<'EOF'
# mac-fswatch

macOS file-watching tool built on [`fsevents`](https://github.com/fsevents/fsevents),
the native Node binding to Apple's FSEvents API. Watches are recursive and
kernel-driven — no polling, no per-file descriptors.

## Requirements

- macOS (the `fsevents` addon only builds/installs on darwin)
- Node.js 18+

## Usage

```sh
npm install
npm start -- ~/some/dir          # human-readable output
npm start -- ~/some/dir --json   # one JSON event per line
npm test
```

As a library:

```js
import { watch } from 'mac-fswatch';

const stop = watch('/path/to/dir', (e) => {
  console.log(e.event, e.type, e.path, e.id);
});
// later: await stop();
```

Each event includes the decoded `event` (`created`, `modified`, `deleted`,
`moved`, …), `type` (`file`, `directory`, `symlink`), `changes` (inode,
finder, access, xattrs), the raw `flags` bitmask, and the FSEvents event `id`.

## Notes

- FSEvents coalesces rapid changes and reports canonical paths
  (e.g. `/private/var/...` instead of `/var/...`).
- `fsevents.constants` is re-exported as `constants` for raw flag checks.
EOF
